const user = {
  id: 42,
  name: 'Ada',
  active: true,
  meta: undefined,     // dropped
  created: new Date('2024-01-15'),
  tags: ['js', 'ts'],
};

const json = JSON.stringify(user);
console.log(json);
// {"id":42,"name":"Ada","active":true,"created":"2024-01-15T00:00:00.000Z","tags":["js","ts"]}

const parsed = JSON.parse(json);
console.log(typeof parsed.created); // 'string' — not a Date!
console.log(parsed.meta);           // undefined — key was dropped

const payload = JSON.stringify({
  id: '9007199254740993',
  at: new Date().toISOString(),
});

const data = JSON.parse(payload, (key, value) => {
  if (key === 'at') return new Date(value);
  if (key === 'id') return BigInt(value);
  return value;
});

console.log(data.id);       // 9007199254740993n
console.log(data.at instanceof Date); // true

// BigInt direct stringify throws:
try {
  JSON.stringify({ n: 1n });
} catch (e) {
  console.log(e.message); // Do not serialize BigInt
}

const original = {
  date: new Date(),
  map: new Map([['a', 1]]),
  nested: { x: 1 },
};
original.self = original; // circular reference

// JSON cannot handle cycles, Map, or preserve Date type:
// JSON.parse(JSON.stringify(original)); // throws on cycle

const clone = structuredClone(original);
console.log(clone.date instanceof Date); // true
console.log(clone.map.get('a'));         // 1
console.log(clone.self === clone);       // true — cycle preserved

